const باب_الإخلاص_وإحضار_النية = {
  رقم_الباب: 1,
  اسم_الباب: "بَابُ الإِخْلَاصِ وَإِحْضَارِ النِّيَّةِ فِي جَمِيعِ الأَعْمَالِ وَالأَقْوَالِ وَالأَحْوَالِ البَارِزَةِ وَالخَفِيَّةِ",
  الكتاب: "رياض الصالحين",
  المؤلف: "الإمام يحيى بن شرف النووي",

  الآيات_القرآنية: [
    { رقم: 1, النص: "وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلَاةَ وَيُؤْتُوا الزَّكَاةَ ۚ وَذَٰلِكَ دِينُ الْقَيِّمَةِ", السورة: "البينة", الآية: 5 },
    { رقم: 2, النص: "لَن يَنَالَ اللَّهَ لُحُومُهَا وَلَا دِمَاؤُهَا وَلَٰكِن يَنَالُهُ التَّقْوَىٰ مِنكُمْ", السورة: "الحج", الآية: 37 },
    { رقم: 3, النص: "قُلْ إِن تُخْفُوا مَا فِي صُدُورِكُمْ أَوْ تُبْدُوهُ يَعْلَمْهُ اللَّهُ", السورة: "آل عمران", الآية: 29 }
  ],

  الأحاديث: [
    { رقم_الحديث: "1", الراوي: "أَمِيرِ المُؤْمِنِينَ أَبِي حَفْصٍ عُمَرَ بْنِ الخَطَّابِ رَضِيَ اللهُ عَنْهُ", المتن: `قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللهِ وَرَسُولِهِ، فَهِجْرَتُهُ إِلَى اللهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا، أَوِ امْرَأَةٍ يَنْكِحُهَا، فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ»`, المخرج: "مُتَّفَقٌ عَلَيْهِ" },
    { رقم_الحديث: "2", الراوي: "أُمِّ المُؤْمِنِينَ عَائِشَةَ رَضِيَ اللهُ عَنْهَا", المتن: `قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «يَغْزُو جَيْشٌ الكَعْبَةَ، فَإِذَا كَانُوا بِبَيْدَاءَ مِنَ الأَرْضِ يُخْسَفُ بِأَوَّلِهِمْ وَآخِرِهِمْ» قَالَتْ: قُلْتُ: يَا رَسُولَ اللَّهِ، كَيْفَ يُخْسَفُ بِأَوَّلِهِمْ وَآخِرِهِمْ وَفِيهِمْ أَسْوَاقُهُمْ وَمَنْ لَيْسَ مِنْهُمْ؟! قَالَ: «يُخْسَفُ بِأَوَّلِهِمْ وَآخِرِهِمْ ثُمَّ يُبْعَثُونَ عَلَى نِيَّاتِهِمْ»`, المخرج: "مُتَّفَقٌ عَلَيْهِ" },
    { رقم_الحديث: "3", الراوي: "عَائِشَةَ رَضِيَ اللهُ عَنْهَا", المتن: `قَالَتْ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «لَا هِجْرَةَ بَعْدَ الفَتْحِ، وَلَكِنْ جِهَادٌ وَنِيَّةٌ، وَإِذَا اسْتُنْفِرْتُمْ فَانْفِرُوا»`, المخرج: "مُتَّفَقٌ عَلَيْهِ" },
    { رقم_الحديث: "4", الراوي: "أَبِي عَبْدِ اللَّهِ جَابِرِ بْنِ عَبْدِ اللَّهِ الأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُمَا", المتن: `قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي غَزَاةٍ، فَقَالَ: «إِنَّ بِالْمَدِينَةِ لَرِجَالًا مَا سِرْتُمْ مَسِيرًا، وَلَا قَطَعْتُمْ وَادِيًا، إِلَّا كَانُوا مَعَكُمْ حَبَسَهُمُ المَرَضُ»`, المخرج: "رَوَاهُ مُسْلِمٌ" },
    { رقم_الحديث: "5", الراوي: "أَبِي يَزِيدَ مَعْنِ بْنِ يَزِيدَ رَضِيَ اللهُ عَنْهُمْ", المتن: `قَالَ: كَانَ أَبِي يَزِيدُ أَخْرَجَ دَنَانِيرَ يَتَصَدَّقُ بِهَا، فَوَضَعَهَا عِنْدَ رَجُلٍ فِي المَسْجِدِ، فَجِئْتُ فَأَخَذْتُهَا فَأَتَيْتُهُ بِهَا. فَقَالَ: وَاللَّهِ، مَا إِيَّاكَ أَرَدْتُ، فَخَاصَمْتُهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: «لَكَ مَا نَوَيْتَ يَا يَزِيدُ، وَلَكَ مَا أَخَذْتَ يَا مَعْنُ»`, المخرج: "رَوَاهُ البُخَارِيُّ" },
    { رقم_الحديث: "6", الراوي: "أَبِي إِسْحَاقَ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ", المتن: `قَالَ: جَاءَنِي رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُنِي عَامَ حَجَّةِ الوَدَاعِ... وَذَكَرَ الحَدِيثَ`, المخرج: "مُتَّفَقٌ عَلَيْهِ" },
    { رقم_الحديث: "7", الراوي: "أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ", المتن: `قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «إِنَّ اللَّهَ لَا يَنْظُرُ إِلَى أَجْسَامِكُمْ، وَلَا إِلَى صُوَرِكُمْ، وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ»`, المخرج: "رَوَاهُ مُسْلِمٌ" },
    { رقم_الحديث: "8", الراوي: "أَبِي مُوسَى الأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ", المتن: `قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الرَّجُلِ يُقَاتِلُ شَجَاعَةً، وَيُقَاتِلُ حَمِيَّةً، وَيُقَاتِلُ رِيَاءً، أَيُّ ذَلِكَ فِي سَبِيلِ اللَّهِ؟ فَقَالَ: «مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ العُلْيَا، فَهُوَ فِي سَبِيلِ اللَّهِ»`, المخرج: "مُتَّفَقٌ عَلَيْهِ" },
    { رقم_الحديث: "9", الراوي: "أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ", المتن: `أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «إِذَا التَقَى المُسْلِمَانِ بِسَيْفَيْهِمَا فَالقَاتِلُ وَالمَقْتُولُ فِي النَّارِ»`, المخرج: "مُتَّفَقٌ عَلَيْهِ" },
    { رقم_الحديث: "10", الراوي: "أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ", المتن: `قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «صَلَاةُ الرَّجُلِ فِي جَمَاعَةٍ تُضَعَّفُ عَلَى صَلَاتِهِ فِي سُوقِهِ وَبَيْتِهِ بِضْعًا وَعِشْرِينَ دَرَجَةً...»`, المخرج: "مُتَّفَقٌ عَلَيْهِ" },
    { رقم_الحديث: "11", الراوي: "ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا", المتن: `عَنْ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِيمَا يَرْوِي عَنْ رَبِّهِ تَبَارَكَ وَتَعَالَى، قَالَ: «إِنَّ اللَّهَ كَتَبَ الحَسَنَاتِ وَالسَّيِّئَاتِ ثُمَّ بَيَّنَ ذَلِكَ...»`, المخرج: "مُتَّفَقٌ عَلَيْهِ" },
    { رقم_الحديث: "12", الراوي: "ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا", المتن: `قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: «انْطَلَقَ ثَلَاثَةُ نَفَرٍ مِمَّنْ كَانَ قَبْلَكُمْ حَتَّى آوَاهُمُ المَبِيتُ إِلَى غَارٍ...»`, المخرج: "مُتَّفَقٌ عَلَيْهِ" }
  ]
};

